                        <?php if ($notifications): ?><div class="notification-list"><?php foreach ($notifications as $notification): ?><a class="notification-row <?= $notification['read_at'] ? '' : 'notification-unread' ?>" href="index.php?view=<?= $user['role'] === 'user' ? 'reports' : 'jobs' ?>"><span class="notification-symbol"><?= $notification['read_at'] ? '·' : '!' ?></span><span><strong><?= e($notification['message']) ?></strong><small><?= e($notification['title']) ?> · <?= e(date('M j, Y · g:i a', strtotime($notification['created_at']))) ?></small></span><b>↗</b></a><?php endforeach; ?></div><?php else: ?><div class="empty-state"><span class="empty-icon">◉</span><strong>You are all caught up</strong><p>Updates about your reports and work will appear here.</p></div><?php endif; ?>
                    </section>
                <?php endif; ?>
                <footer class="page-footer"><span><?= e($appName) ?> <i>·</i> Community to crew, connected.</span><span>Roadline network <b></b> Operational</span></footer>
            </div>
        </main>
    </div>
<?php endif; ?>
<?php if ($user && $user['role'] === 'user' && $view === 'reports'): ?><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js" crossorigin=""></script><?php endif; ?>
<script src="assets/app.js" defer></script>
</body>
</html>